def shell(lang,path,title,description,body,form=False):
 c=C[lang];alt=('/racconta-idea/' if lang=='en' else '/en/share-your-idea/') if form else c['other'];it=path if lang=='it' else alt;en=path if lang=='en' else alt
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | RendimentoBB</title><meta name="description" content="{esc(description,quote=True)}"><meta name="theme-color" content="#086c53"><link rel="canonical" href="https://www.rendimentobb.it{path}"><link rel="alternate" hreflang="it" href="https://www.rendimentobb.it{it}"><link rel="alternate" hreflang="en" href="https://www.rendimentobb.it{en}"><link rel="alternate" hreflang="x-default" href="https://www.rendimentobb.it{it}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="https://www.rendimentobb.it{path}"><meta property="og:image" content="https://www.rendimentobb.it/img/dashboard-preview.png"><meta property="og:locale" content="{'it_IT' if lang=='it' else 'en_GB'}"><link rel="icon" href="/img/favicon.svg"><link rel="stylesheet" href="/css/basic-beyond.css?v=20261019-rc155"><script src="/js/basic-beyond-knowledge.js?v=20261019-rc155" defer></script><script src="/js/basic-beyond-public.js?v=20261019-rc155" defer></script></head><body class="bb-page"><a class="bb-skip" href="#main">{'Vai al contenuto' if lang=='it' else 'Skip to content'}</a><header class="bb-header"><div class="bb-wrap"><a class="bb-brand" href="/{'?lang=en' if lang=='en' else ''}">Rendimento<span>BB</span></a><nav aria-label="{'Navigazione' if lang=='it' else 'Navigation'}"><a href="/{'?lang=en' if lang=='en' else ''}">{c['home']}</a><a href="{c['base']}"{' aria-current="page"' if not form else ''}>Basic & Beyond</a><a href="{c['form']}"{' aria-current="page"' if form else ''}>{c['idea']}</a><a href="{alt}" lang="{'en' if lang=='it' else 'it'}" hreflang="{'en' if lang=='it' else 'it'}">{c['lang']}</a></nav></div></header><main id="main" class="bb-wrap">{body}</main><footer class="bb-footer"><div class="bb-wrap"><p>{c['footer']}</p><a href="/privacy.html{'?lang=en' if lang=='en' else ''}#basic-beyond-privacy">{c['privacy']}</a><a href="/terms.html{'?lang=en' if lang=='en' else ''}">{c['terms']}</a><a href="/contact.html{'?lang=en' if lang=='en' else ''}">{'Contatti' if lang=='it' else 'Contact'}</a><a href="{c['form']}#privacy">{c['noticeTitle']}</a></div></footer></body></html>'''
for lang,c in C.items():
 body=f'<section class="bb-hero"><p class="bb-kicker">RendimentoBB — Basic & Beyond · {c["tag"]}</p><h1>{c["title"]}</h1><p>{c["lead"]}</p><div class="bb-actions"><a class="bb-btn" href="{c["form"]}">{c["idea"]}</a><a class="bb-btn secondary" href="#solutions">{c["solutions"]}</a></div></section><div class="bb-ribbon">{mark}<span>{c["notice"]}</span></div><section class="bb-section"><p class="bb-kicker">RendimentoBB → Basic & Beyond</p><h2>{c["origin"]}</h2><p>{c["originText"]}</p></section><section class="bb-section"><h2>{c["path"]}</h2><ol class="bb-path">'+''.join(f'<li><strong>{a}</strong><span>{b}</span></li>' for a,b in c['steps'])+'</ol></section>'
 body+=f'<section id="solutions" class="bb-section"><h2>{c["solutions"]}</h2><p>{c["solutionsText"]}</p><div class="bb-grid">'+''.join(f'<article class="bb-card"><span class="bb-index">0{i+1} · {a}</span><h3>{b}</h3><p>{d}</p><a href="{url}">{cta} →</a></article>' for i,(a,b,d,cta,url) in enumerate(c['cases']))+f'</div><p class="bb-note">{c["demoNote"]}</p></section>'
 body+=f'<section id="roadmap" class="bb-section"><p class="bb-kicker">Roadmap</p><h2>{c["roadmap"]}</h2><div class="bb-roadmap">'+''.join(f'<article><span class="bb-status {"planned" if i==1 else "considering" if i==2 else ""}">{c["statuses"][i]}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(c['roadItems']))+'</div></section>'
 body+=f'<section class="bb-section"><h2>{c["guide"]}</h2><div class="bb-actions">'+''.join(f'<button type="button" data-bb-question="{esc(q,quote=True)}">{q}</button>' for q in c['guideQ'])+'</div><p id="bb-answer" class="bb-message" role="status" aria-live="polite" hidden></p></section>'
 body+=f'<section class="bb-section"><h2>{c["feedbackTitle"]}</h2><p>{c["feedback"]}</p><a class="bb-btn" href="{c["form"]}">{c["idea"]}</a></section>'
 p=root/c['base'].strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(shell(lang,c['base'],'Basic & Beyond — '+c['tag'],c['lead'],body))
 choices=''.join(f'<label class="bb-check"><input type="checkbox" name="types" value="{v}"><span>{label}</span></label>' for v,label in zip(['website','management','dashboard','app','automation','other','unsure'],c['types']))
 form=f'''<section class="bb-hero"><p class="bb-kicker">Basic & Beyond · {c['idea']}</p><h1>{c['formTitle']}</h1><p>{c['formLead']}</p></section><div class="bb-form-layout"><form id="bb-idea-form" class="bb-form" method="post" action="/api/solution-requests" data-lang="{lang}"><noscript><p>{c['js']}</p></noscript><fieldset><legend>{c['fieldsets'][0]}</legend><label for="problem">{c['problem']}</label><textarea id="problem" name="problem" required minlength="20" maxlength="1500" aria-describedby="problem-hint"></textarea><p id="problem-hint" class="bb-hint">{c['problemHint']}</p><label for="outcome">{c['outcome']}</label><textarea id="outcome" name="outcome" maxlength="1500"></textarea><label for="description">{c['description']}</label><textarea id="description" name="description" maxlength="3000"></textarea></fieldset><fieldset><legend>{c['fieldsets'][1]}</legend><label for="level">{c['level']}</label><select id="level" name="level" required>'''+''.join(f'<option value="{v}">{label}</option>' for v,label in zip(['','beginner','intermediate','expert'],c['levels']))+f'''</select><p id="types-label">{c['typeTitle']}</p><div class="bb-options" role="group" aria-labelledby="types-label">{choices}</div></fieldset><fieldset><legend>{c['fieldsets'][2]}</legend><label for="email">{c['email']}</label><input type="email" id="email" name="email" maxlength="254" autocomplete="email" aria-describedby="email-hint"><p class="bb-hint" id="email-hint">{c['emailHint']}</p><label class="bb-check"><input type="checkbox" name="contactMe"><span>{c['contact']}</span></label><label class="bb-check"><input type="checkbox" name="processingConsent" required><span>{c['processing']} <a href="#privacy">{c['noticeTitle']}</a></span></label><label class="bb-check"><input type="checkbox" name="marketingConsent"><span>{c['marketing']}</span></label></fieldset><div class="bb-trap" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><p class="bb-note">{c['safety']}</p><button type="submit" id="bb-submit">{c['submit']}</button><p id="bb-form-status" class="bb-message" role="status" tabindex="-1" aria-live="polite" hidden></p></form><aside class="bb-card"><p class="bb-kicker">Basic & Beyond</p><h2>{c['sideTitle']}</h2><p>{c['sideText']}</p><p class="bb-note">{c['notice']}</p><a href="{c['base']}#roadmap">Roadmap →</a></aside></div><section id="privacy" class="bb-section bb-privacy"><h2>{c['noticeTitle']}</h2><p>{c['noticeText']}</p><p>{c['noticeMore']}</p><p>{c['noticeRights']}</p><a href="/privacy.html{'?lang=en' if lang=='en' else ''}">{c['privacy']} →</a></section>'''
 p=root/c['form'].strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(shell(lang,c['form'],c['idea']+' — Basic & Beyond',c['formLead'],form,True))
